    def perform_recommissioning(self, **kwargs):
        """
        This function recommissions(delta or parameter) BTS.
        @param kwargs:
            type: delta/param/ncf

            Common:
            timeout: int, Time to wait for positive procedure result
            alias: string, Name of execution context

            In case of type=delta:
            delta_file: string, if type is delta. Delta file name should be passed
            force_reset: bool, Force resets if True
            auto_lock_cells: bool, Auto lock cells if True
            should_activate: bool, True by default.

            In case of type=param:
            ncf: bool, ncf
            param_path: string, parameter path
            operation: string, operation
            value: string, value

        @return

        @raise
            Exception

        """

        if kwargs['type'] == 'delta':
            delta_file = kwargs['delta_file']
            alias = kwargs.pop("alias", "default")
            # force_reset = kwargs.pop('force_reset', False)
            # auto_lock_cells = kwargs.pop('auto_lock_cells', False)
            should_activate = kwargs.pop("should_activate", True)
            parser_obj = DeltaParser(delta_file)
            jsonfile = parser_obj.convert_delta_xml_to_json()
            # timeout = kwargs.pop('timeout', 120)

            # delta_file = self.get_delta_file_full_path(delta_file=delta_file, alias=alias)
            # parser_obj = DeltaParser(delta_file)
            # json_file = parser_obj.convert_delta_xml_to_json()
            # self._perform_delta_commissioning(jsonfile=json_file, force_reset=force_reset,
            #                                   auto_lock_cells=auto_lock_cells,
            #                                   should_activate=should_activate, timeout=timeout,
            #                                   alias=alias)
            self.factory.vdu_oam.perform_delta_recommissioning(delta_file=jsonfile, wait_for_completion=True,
                                                               should_activate=should_activate, timeout=300, vdu_connection=alias)
        elif kwargs['type'] == 'param':
            self._perform_parameter_recommissioning(**kwargs)
            ncf = kwargs.get('ncf', False)
            # if ncf is False:
            # _generate_scf(kwargs.get('alias', 'default'), kwargs.get('timeout', 120))
        elif kwargs['type'] == 'ncf':
            self._perform_ncf_commissioning(**kwargs)

    def _perform_delta_commissioning(self, jsonfile, force_reset, auto_lock_cells,
                                     should_activate, timeout, alias):
        delta_generated = None
        fail = False
        try:
            plan_name = "Delta_Plan_{}".format(datetime.now().strftime('%m_%d_%y_%H_%M_%S'))
            # Create a delta file
            delta_generated = self.factory.vdu_oam.generate_delta_plan(plan_name=plan_name, vdu_connection=alias)
            logger.debug("Response from generate delta plan {}".format(delta_generated))

            # Verify delta file is created successfully
            self._verify_action_state_of_delta_plan(operation="generate",
                                                    action_id=delta_generated['action_id'],
                                                    alias=alias)
            with open(jsonfile) as delta_json:
                delta_dict = json.load(delta_json)
                logger.debug(delta_dict)

            # Update parameters to the generated delta file
            self._cu_add_update_parameters_to_delta(delta_generated['plan_id'], delta_dict, alias)
            validation = self.factory.vdu_oam.validate_delta_plan(delta_plan_id=delta_generated[
                'plan_id'], vdu_connection=alias)
            logger.debug("Response from validate delta plan {}".format(validation))

            # Validate delta plan
            logger.debug("Validating delta plan")
            self._verify_action_state_of_delta_plan(operation="validate",
                                                    plan_id=delta_generated['plan_id'],
                                                    action_id=validation['action_id'], alias=alias)
            # Activate delta plan
            if should_activate:
                activation = self.factory.vdu_oam.activate_delta_plan(
                    delta_plan_id=delta_generated['plan_id'],
                    force_reset=force_reset,
                    auto_lock_cells=auto_lock_cells,
                    vdu_connection=alias)
                time.sleep(10)
                logger.debug("Response from activate delta plan {}".format(activation))
                self._verify_action_state_of_delta_plan(operation="activate",
                                                        plan_id=delta_generated['plan_id'],
                                                        operation_id=activation['id'],
                                                        alias=alias, timeout=timeout)
                logger.debug("Delta Commissioning succeeded")
        except Exception as e:
            logger.debug("Delta commissioning Failed due to:: {}".format(e))
            raise CommissioningException(e)

    #        finally:
    ##            time.sleep(300)
    #            if 'plan_id' in delta_generated:
    #                self.factory.cu_oam.delete_delta_plan(plan_id=delta_generated['plan_id'],
    #                                                      vdu_connection=alias)

    def _upload_plan_file(self, scf_file, alias):
        bts_id, scf_dir = self._get_btsid_and_scf_dir(alias)
        scf_file = os.path.join(scf_dir, scf_file)
        logger.debug('scf_file', scf_file)
        output = self.factory.vdu_oam.upload_plan(path_to_plan_file=scf_file, plan_name='fw_plan', vdu_connection=alias)
        plan_id = output['plan_id']
        return plan_id

    def _plan_validation(self, plan_id, timeout, alias):
        output = self.factory.vdu_oam.validate_plan(plan_id=plan_id, vdu_connection=alias)
        operation_id = output['action_id']
        self._check_operation_state(plan_id, operation_id, method='validate_plan', timeout=timeout,
                                    vdu_connection=alias)

    def _plan_activation(self, plan_id, timeout, alias):
        output = self.factory.vdu_oam.activate_plan(plan_id=plan_id, vdu_connection=alias, timeout=500)
        operation_id = output['id']
        self._check_operation_state(plan_id, operation_id, method='activate_plan', timeout=100, vdu_connection=alias)

