    def _check_operation_state(self, *args, **kwargs):
        status = ''
        error_message = None
        wait_time = 0
        timeout = kwargs.pop('timeout')
        # get_upload_plan_operation_status
        method = 'get_{}_operation_status'.format(kwargs.pop('method'))
        method_callable = getattr(self.factory.vdu_oam,
                                  method)  # (plan_id=args[0], operation_id=args[1], vdu_connection=args[2])
        sleep(timeout)
        try:
            output = method_callable(*args, **kwargs)
        except Exception as a_e:
            logger.debug('Err while checking status: {}'.format(a_e))
        logger.debug(str(output))
        status = output['status']
        if status != 'success':
            #            error_message = output['error_message'] if output.has_key('error_message') else None
            error_message = output['error_message'] if 'error_message' in output else None
            if error_message is not None:
                raise CommissioningException('Error: {}'.format(error_message))

    def _get_btsid_and_scf_dir(self, alias):
        chained = global_vars.alias_chained_dict.get(alias)
        dut = global_vars.alias_dut_dict.get(alias)
        if chained:
            bts_id = get_config_variable([dut, 'bts_id'])
            scf_dir = get_config_variable(['chained_bts_scf_dir']).format(chained=bts_id)
        else:
            bts_id = get_config_variable(['bts_id'])
            scf_dir = get_config_variable(['scfc_path'])
        logger.debug("btsid :: {0}\tscf_dir :: {1}".format(bts_id, scf_dir))
        return bts_id, scf_dir

    def _perform_parameter_recommissioning(self, **kwargs):
        distname, param_name = kwargs['param_path'].split(':')
        if not distname.startswith('MRBTS-'):  ## If not already a full distname
            distname = self.distnames.get_full_distname_from_scf(
                distname_suffix=distname, format_distname=False, alias=kwargs.get("alias", "default"))
            # distname = self.distnames.format_to_infomodel_compatible_distname(distname)
        logger.debug("perform parameter recommissioning....")
        self.factory.admin.perform_parameter_recommissioning(
            distname, param_name, kwargs['operation'], kwargs['value'],
            skip_parameter_relation_errors=kwargs.get('skip_parameter_relation_errors', True),
            timeout=kwargs.get('timeout', 120), alias=kwargs.get("alias", "default"))

    def _verify_action_state_of_delta_plan(self, operation, alias, action_id=None,
                                           operation_id=None,
                                           plan_id=None,
                                           activation_status='success',
                                           timeout=120):
        actual_status = ''
        wait_time = 0
        while actual_status != activation_status and wait_time < int(timeout):
            if operation.lower() == 'generate':
                output = self.factory.vdu_oam.get_delta_plan_generated_action_status(
                    action_id=action_id, vdu_connection=alias)
            elif operation.lower() == 'validate':
                output = self.factory.vdu_oam.get_validate_delta_plan_operation_status(
                    delta_plan_id=plan_id, action_id=action_id, vdu_connection=alias)
            elif operation.lower() == 'activate':
                output = self.factory.vdu_oam.get_activate_delta_plan_operation_status(
                    delta_plan_id=plan_id, operation_id=operation_id, vdu_connection=alias)
            elif operation.lower() == 'update':
                output = self.factory.vdu_oam.get_update_paras_action_status_of_delta_plan(
                    plan_id=plan_id, action_id=action_id, vdu_connection=alias)
            else:
                raise CommissioningException('Invalid operation type given to verify '
                                             'action state of delta plan. Valid operations are'
                                             '1. Generate \n 2. Update \n 3. Validate \n'
                                             '4. Activate')
            actual_status = output['status']
            sleep(5)
            wait_time += 5
        else:
            if actual_status.lower() != "success":
                logger.debug("Delta {} failed".format(operation))
                logger.debug("{}".format(traceback.format_exc()))
                raise CommissioningException('Error while verifying delta plan {} operation : {}'
                                             .format(operation, output))
        logger.debug("Delta {} succeeded".format(operation))

    def get_mo_uuid(self, plan_id, mo_dn, create_moc, alias):
        name_list = mo_dn.split("/")
        if create_moc:
            name_list = name_list[0:-1]
        delta_plan_tree = self.factory.vdu_oam.get_tree_of_delta_plan(plan_id=plan_id,
                                                                      vdu_connection=alias)
        # logger.debug("delta_tree {}".format(delta_plan_tree))
        parent_mo_uuid = 'None'
        for name in name_list:
            logger.debug("Name is {}".format(name))
            parent_mo_uuid = self.get_mo_uuid_by_name(plan_id, parent_mo_uuid, name, alias,
                                                      delta_plan_tree)
            logger.debug("parent_mo_uuid for {} is {}".format(name, parent_mo_uuid))
        return parent_mo_uuid

    def get_mo_uuid_by_name(self, plan_id, parent_mo_uuid, name, alias, delta_plan_tree=None):
        mo_uuid = ''
        delta_plan_tree = delta_plan_tree or self.factory.vdu_oam.get_tree_of_delta_plan(
            plan_id=plan_id, vdu_connection=alias)
        #        for mo_dict in delta_plan_tree["created"]:
        for mo_dict in delta_plan_tree:
            # logger.debug("MO is {} name:{} mo_uuid: {}\npassed: parent:{} name:{}".format(mo_dict, mo_dict["name"], mo_dict['parent_mo_uuid'], parent_mo_uuid, name))
            if str(mo_dict["parent_mo_uuid"] or None) == parent_mo_uuid and mo_dict["name"] == name:
                mo_uuid = mo_dict["mo_uuid"]
                logger.debug("Found the mo_uuid {} {}".format(name, mo_uuid))
                break
        else:
            logger.debug("Could not find the mo_uuid for the param {}".format(name))
            raise Exception("Could not find the mo_uuid for the param {}".format(name))
        return mo_uuid

    def get_delta_file_full_path(self, delta_file, alias):
        delta_dir = get_config_variable(['delta_files'])
        bts_id, delta_dir = self.get_config_files_from_corresponding_bts_dir(
            delta_dir, alias)
        return os.path.join(delta_dir, delta_file)

    def get_config_files_from_corresponding_bts_dir(self, bts_config_file_path, alias):
        """
            This function returns bts config files like scf_file and delta_file
            etc. from the config directory of the primary bts or chain bts
        """
        # logger.debug("obtaining scf full path...")
        chained = global_vars.alias_chained_dict.get(alias)
        dut = global_vars.alias_dut_dict.get(alias)
        bts_id = get_config_variable(['bts_id'])

        if chained:
            chained_bts_id = get_config_variable([dut, 'bts_id'])
            # scf_dir = _get_config_variable(['chained_bts_scf_dir']).format(
            #     chained=bts_id)
            bts_config_file_path = bts_config_file_path.replace('/{}/'.format(
                bts_id), '/{}/'.format(chained_bts_id))
            bts_id = chained_bts_id
        return bts_id, bts_config_file_path

    def _cu_add_update_parameters_to_delta(self, plan_id, parameters, alias):
        #        op_mapping = {"update": "replace"}
        op_mapping = {"update": "add"}
        nidds = self.factory.vdu_oam.get_nidd(alias)
        all_mocs_nidds = {mocs["class_name"]: mocs['nidd_id'] for mocs in nidds}
        for dn_dict in parameters:
            if dn_dict["operation"] == "delete":
                # Create moc for delta plan and then perform update operation
                try:
                    moc_name = dn_dict['distName'].split("/")[-1].split("-")[0]
                    full_moc_name = dn_dict['distName'].split("/")[-1]
                    logger.debug("moc name: {}".format(full_moc_name))
                    if moc_name in all_mocs_nidds.keys():
                        nidd_id_create = all_mocs_nidds[moc_name]
                    delta_plan_tree = self.factory.vdu_oam.get_tree_of_delta_plan(plan_id=plan_id, vdu_connection=alias)
                    for mo_dict in delta_plan_tree["created"]:
                        logger.debug("MO is {} name:{}".format(mo_dict, mo_dict["name"]))
                        if mo_dict["name"] == full_moc_name:
                            mo_uuid = mo_dict["mo_uuid"]
                            logger.debug("Found the mo_uuid {} {}".format(full_moc_name, mo_uuid))
                            break
                    else:
                        logger.debug("Could not find the mo_uuid for the param {}".format(full_moc_name))
                        raise Exception("Could not find the mo_uuid for the param {}".format(full_moc_name))

                    logger.debug("Deleting moc for {0}, nidd_id: {1}".format(dn_dict['distName'], nidd_id_create))
                    return_create_mo = self.factory.vdu_oam.delete_mo_of_delta_plan(delta_plan_id=plan_id,
                                                                                    mo_dn=mo_uuid,
                                                                                    vdu_connection=alias)
                    logger.debug("Delete mo of delta plan returned: {}".format(json.dumps(return_create_mo, indent=4)))
                    continue
                except Exception as e:
                    raise Exception("Deleting MO failed :{}".format(str(e)))
            elif dn_dict["operation"] == "create":
                # Create moc for delta plan and then perform update operation
                try:
                    moc_name = dn_dict['distName'].split("/")[-1].split("-")[0]
                    if moc_name in all_mocs_nidds.keys():
                        nidd_id_create = all_mocs_nidds[moc_name]
                    logger.debug("Creating moc for {0}, nidd_id: {1}".format(dn_dict['distName'], nidd_id_create))
                    #parent_mo_uuid = self.get_mo_uuid(plan_id, dn_dict["distName"], True, alias)
                    mo_name = dn_dict['distName'].split("/")[-1]
                    parent_mo_dn = dn_dict['distName'].rsplit("/",1)[0]
                    return_create_mo = self.factory.vdu_oam.create_vdu_object_of_delta_plan(delta_plan_id=plan_id,
                                                                                                parent_mo_dn=parent_mo_dn,
                                                                                                mo_name=mo_name,
                                                                                                include_defaults=True,
                                                                                                vdu_connection=alias)
                    time.sleep(10)
                    logger.debug("create mo of delta plan returned: {}".format(json.dumps(return_create_mo, indent=4)))
                except Exception as e:
                    raise Exception("Creating MO failed :{}".format(str(e)))

            mo_uuid = self.get_mo_uuid(plan_id, dn_dict["distName"], False, alias)
            time.sleep(10)
            parameter_change_list = []
            for param in dn_dict["parameters"]:
                logger.debug("each param dict is {}".format(param))
                if isinstance(param["value"], list):
                    # parameter_change_list = self._update_list_parameter(op_mapping=op_mapping, param=param)
                    parameter_change_list.append(self._update_list_parameter(op_mapping=op_mapping, param=param))
                    try:
                        param_list = {}
                        param_list['value'] = ""
                        #param_list['operation_type'] = 'add'
                        param_list['parameter_path'] = '/' + param['parameterName']
                        #param_list = [param_list]
                        # logger.debug("Passing to delta: {} {} {}".format(plan_id, mo_uuid, param_list[0]))
                        update_delta = self.factory.vdu_oam.update_vdu_parameter_of_delta_plan(plan_id=plan_id,
                                                                                               mo_dn=dn_dict['distName'],
                                                                                               updated_paras_dict={param_list["parameter_path"]: param_list['value']},
                                                                                               operation='add',
                                                                                               vdu_connection=alias)
                        logger.debug("Response from update parameters of delta plan is {}".format(update_delta))
                        self._verify_action_state_of_delta_plan(operation="update", plan_id=plan_id,
                                                                action_id=update_delta['action_id'],
                                                                alias=alias)
                    except Exception as list_e:
                        logger.debug("Failed to create list param in moc:{}".format(list_e))
                        raise Exception("Failed to create {} list in moc".format(param))
                else:
                    parameter_change_list_local = []
                    # obj_info = self.factory.get_current_plan_objects()
                    param_change_dict_temp = {"operation_type": op_mapping[param["operation"]],
                                              'parameter_path': "/{}".format(param["parameterName"]),
                                              'value': param["value"]}
                    logger.debug("param_change_dict_temp is {}".format(param_change_dict_temp))
                    parameter_change_list_local.append(param_change_dict_temp)
                    parameter_change_list.append(parameter_change_list_local)
                logger.debug("Inside loop: parameter_change_list: {}".format(parameter_change_list))
            logger.debug("Outside loop: parameter_change_list: {}".format(parameter_change_list))
            # vdu_oam.update_parameters_of_delta_plan('dp_00000000', '0c832650-8169-419b-81e4-80711a54fd34', [{'operation_type': 'add', 'parameter_path': '/nrRanTraceReference', 'value': ""}])

            for change_list in parameter_change_list:
                if len(change_list) == 1:
                    change_list = change_list[0]
                    update_delta = self.factory.vdu_oam.update_vdu_parameter_of_delta_plan(
                        plan_id=plan_id, mo_dn=dn_dict['distName'],
                        updated_paras_dict={change_list["parameter_path"].strip('/'): change_list['value']},
                        operation=change_list["operation_type"], mo_uuid=mo_uuid, vdu_connection=alias)
                    # get_action_state_of_updating_parameters_of_delta_plan(plan_id, action_id, vdu_connection=alias)

                    logger.debug("Response from update parameters of delta plan is {}".format(update_delta))
                    self._verify_action_state_of_delta_plan(operation="update", plan_id=plan_id,
                                                            action_id=update_delta['action_id'],
                                                            alias=alias)
                else:
                    logger.info("updating a list of parameters")
                    for change in change_list:
                        # print("change in list",change)
                        change = change[0]
                        updated_change_dict={change["parameter_path"]: change['value']}
                        # print("updated_paras_dict when length 1 {}".format(updated_change_dict))
                        update_delta = self.factory.vdu_oam.update_vdu_parameter_of_delta_plan(
                            plan_id=plan_id, mo_dn=dn_dict['distName'], updated_paras_dict=updated_change_dict,
                            operation=change["operation_type"], vdu_connection=alias)
                        # get_action_state_of_updating_parameters_of_delta_plan(plan_id, action_id, vdu_connection=alias)

                        logger.debug("Response from update parameters of delta plan is {}".format(update_delta))
                        self._verify_action_state_of_delta_plan(operation="update", plan_id=plan_id,
                                                                action_id=update_delta['action_id'],
                                                                alias=alias)

    def _update_list_parameter(self, op_mapping, param):
        """
            Update list parameter
        """
        logger.debug("in _update_list_parameter: param:  {}".format(param))
        parameter_change_list = []
        for index, val in enumerate(param['value']):
            if isinstance(val, dict):
                for key, va in list(val.items()):
                    parameter_change_list_local = []
                    logger.debug("multiple value testing")
                    param_change_dict_temp = {
                        "operation_type": op_mapping[param["operation"]],
                        'parameter_path': "/{}/{}/{}".format(param["parameterName"],
                                                             index, key),
                        'value': va}
                    parameter_change_list_local.append(param_change_dict_temp)
                    parameter_change_list.append(parameter_change_list_local)
            else:
                parameter_change_list_local = []
                param_change_dict_temp = {
                    "operation_type": op_mapping[param["operation"]],
                    'parameter_path': "/{}/{}".format(param["parameterName"], index),
                    'value': val}
                parameter_change_list_local.append(param_change_dict_temp)
                parameter_change_list.append(parameter_change_list_local)
        return parameter_change_list

