    def get_operation_state(self, **kwargs):
        plan_type = kwargs.get("plan_type", "activating")
        operation_id = kwargs["operation_id"]
        connection = kwargs.get("alias", "default")

        if plan_type == "activating":
            plan_id = kwargs["plan_id"]
            return self.factory.vdu_oam.get_activate_plan_operation_status(plan_id, operation_id,
                                                                           vdu_connection=connection)
        elif plan_type == "uploading":
            return self.factory.vdu_oam.get_upload_plan_operation_status(operation_id, vdu_connection=connection)
        elif plan_type == "validating":
            plan_id = kwargs["plan_id"]
            return self.factory.vdu_oam.get_validate_plan_operation_status(plan_id, operation_id,
                                                                           vdu_connection=connection)

